1: /**
2:  * 决策范围「选择户室」弹窗：楼幢树勾选、全选楼幢、切换楼幢保留勾选
3:  */
4: export default {
5:   data() {
6:     return {
7:       buildingSelectRevision: 0,
8:       buildingCheckCache: {
9:         treeKey: 'buildingVId',
10:         byId: {},
11:         isAllSelected: false,
12:         isAllIndeterminate: false
13:       }
14:     }
15:   },
16:   computed: {
17:     buildingCheckbox() {
18:       void this.buildingSelectRevision
19:       const cache = this.buildingCheckCache
20:       const { treeKey, byId } = cache
21:       return {
22:         isAllSelected: cache.isAllSelected,
23:         isAllIndeterminate: cache.isAllIndeterminate,
24:         onToggleAll: (checked) => this.setSelectAllBuildings(checked),
25:         isBuildingSelected: (building) => byId[building?.[treeKey]]?.allSelected ?? false,
26:         isBuildingIndeterminate: (building) => byId[building?.[treeKey]]?.indeterminate ?? false,
27:         onToggleBuilding: (building, checked) => this.toggleBuilding(building, checked)
28:       }
29:     }
30:   },
31:   methods: {
32:     isHouseChecked(house) {
33:       return house.checked == 1 || house.checked === '1'
34:     },
35:     isHouseToggleable(house) {
36:       return house.exist != 1
37:     },
38:     getDialogTreeMeta() {
39:       const dialog = this.$refs.dialog
40:       return {
41:         dialog,
42:         treeData: dialog?.treeData || [],
43:         treeKey: dialog?.tree?.treeKey || 'buildingVId'
44:       }
45:     },
46:     forEachFloorHouses(floors, callback) {
47:       (floors || []).forEach((floor) => {
48:         (floor.unitHouses || []).forEach((unit) => {
49:           (unit.tlpHouses || []).forEach((house) => {
50:             callback(house, { floor, unit })
51:           })
52:         })
53:       })
54:     },
55:     resolveBuildingFloors(building) {
56:       const { dialog, treeKey } = this.getDialogTreeMeta()
57:       const selectedKey = dialog?.treeSelection?.[treeKey]
58:       const buildingKey = building?.[treeKey]
59:       if (treeKey && selectedKey != null && selectedKey === buildingKey && this.buildingTableData?.length) {
60:         return this.buildingTableData
61:       }
62:       return building.floorHouses || []
63:     },
64:     forEachHouseInTreeData(callback) {
65:       const { treeData } = this.getDialogTreeMeta()
66:       treeData.forEach((building) => {
67:         this.forEachHouseInBuilding(building, callback)
68:       })
69:     },
70:     forEachHouseInBuilding(building, callback) {
71:       this.forEachFloorHouses(this.resolveBuildingFloors(building), callback)
72:     },
73:     forEachHouseInBuildingSource(building, callback) {
74:       this.forEachFloorHouses(building.floorHouses, callback)
75:     },
76:     setFloorsChecked(floors, checked) {
77:       const value = checked ? '1' : '0'
78:       this.forEachFloorHouses(floors, (house) => {
79:         house.checked = value
80:       })
81:     },
82:     applyCheckedToAllBuildings(checked) {
83:       const { treeData } = this.getDialogTreeMeta()
84:       treeData.forEach((building) => {
85:         this.setFloorsChecked(building.floorHouses, checked)
86:       })
87:       this.setFloorsChecked(this.buildingTableData, checked)
88:     },
89:     applyCheckedToBuilding(building, checked) {
90:       this.setFloorsChecked(building.floorHouses, checked)
91:       const { dialog, treeKey } = this.getDialogTreeMeta()
92:       const selectedKey = dialog?.treeSelection?.[treeKey]
93:       if (selectedKey != null && selectedKey === building?.[treeKey]) {
94:         this.setFloorsChecked(this.buildingTableData, checked)
95:       }
96:     },
97:     initAllHousesInTree() {
98:       this.forEachHouseInTreeData((house) => {
99:         this.initHouseChecked(house)
100:       })
101:     },
102:     computeBuildingState(building) {
103:       let hasHouse = false
104:       let allSelected = true
105:       let anySelected = false
106: 
107:       this.forEachHouseInBuildingSource(building, (house) => {
108:         hasHouse = true
109:         if (this.isHouseChecked(house)) {
110:           anySelected = true
111:         } else {
112:           allSelected = false
113:         }
114:       })
115: 
116:       if (!hasHouse) {
117:         this.forEachHouseInBuilding(building, (house) => {
118:           hasHouse = true
119:           if (this.isHouseChecked(house)) {
120:             anySelected = true
121:           } else {
122:             allSelected = false
123:           }
124:         })
125:       }
126: 
127:       return {
128:         hasHouse,
129:         allSelected: hasHouse && allSelected,
130:         anySelected,
131:         indeterminate: anySelected && !(hasHouse && allSelected)
132:       }
133:     },
134:     rebuildGlobalCheckState(byId, treeData, treeKey) {
135:       let allSelected = true
136:       let anySelected = false
137: 
138:       treeData.forEach((building) => {
139:         const state = byId[building[treeKey]] || {
140:           hasHouse: false,
141:           allSelected: false,
142:           anySelected: false,
143:           indeterminate: false
144:         }
145:         if (!state.hasHouse) {
146:           allSelected = false
147:           return
148:         }
149:         if (state.allSelected) {
150:           anySelected = true
151:         } else {
152:           allSelected = false
153:           if (state.anySelected || state.indeterminate) {
154:             anySelected = true
155:           }
156:         }
157:       })
158: 
159:       const isAllSelected = treeData.length > 0 && allSelected
160:       return {
161:         isAllSelected,
162:         isAllIndeterminate: anySelected && !isAllSelected
163:       }
164:     },
165:     refreshBuildingCheckCache(buildingIds = null) {
166:       const { treeData, treeKey } = this.getDialogTreeMeta()
167:       const byId = buildingIds ? { ...this.buildingCheckCache.byId } : {}
168: 
169:       const targets = buildingIds
170:         ? treeData.filter((building) => buildingIds.includes(building[treeKey]))
171:         : treeData
172: 
173:       targets.forEach((building) => {
174:         byId[building[treeKey]] = this.computeBuildingState(building)
175:       })
176: 
177:       const globalState = this.rebuildGlobalCheckState(byId, treeData, treeKey)
178:       this.buildingCheckCache = {
179:         treeKey,
180:         byId,
181:         ...globalState
182:       }
183:       this.buildingSelectRevision += 1
184:     },
185:     notifyBuildingSelectChange(buildingIds = null) {
186:       this.refreshBuildingCheckCache(buildingIds)
187:     },
188:     syncSelectionViews() {
189:       this.refreshBuildingCheckCache()
190:       this.$nextTick(() => {
191:         this.syncListSelection?.()
192:       })
193:     },
194:     getBuildingId(building) {
195:       const { treeKey } = this.getDialogTreeMeta()
196:       return building?.[treeKey]
197:     },
198:     initHouseChecked(house) {
199:       if (house.exist == 1) {
200:         house.checked = '1'
201:         return
202:       }
203:       if (house.checked === undefined || house.checked === null || house.checked === '') {
204:         house.checked = '0'
205:       }
206:     },
207:     onTreeClick(row) {
208:       const { floorHouses } = row
209:       this.buildingTableData = floorHouses
210:       this.forEachHouseInBuilding(row, (house) => {
211:         this.initHouseChecked(house)
212:       })
213:       this.$nextTick(() => {
214:         this.notifyBuildingSelectChange([this.getBuildingId(row)])
215:         this.syncListSelection?.()
216:       })
217:     },
218:     onBuildingTreeLoaded() {
219:       this.$nextTick(() => {
220:         this.initAllHousesInTree()
221:         this.syncSelectionViews()
222:       })
223:     },
224:     setSelectAllBuildings(checked) {
225:       const selectAll = checked === true || checked === '1' || checked === 1
226:       this.applyCheckedToAllBuildings(selectAll)
227:       this.syncSelectionViews()
228:     },
229:     toggleSelectAllBuildings() {
230:       this.setSelectAllBuildings(!this.buildingCheckCache.isAllSelected)
231:     },
232:     toggleBuilding(building, checked) {
233:       const id = this.getBuildingId(building)
234:       const currentSelected = this.buildingCheckCache.byId[id]?.allSelected ?? false
235:       const selectAll = checked !== undefined
236:         ? (checked === true || checked === '1' || checked === 1)
237:         : !currentSelected
238:       this.applyCheckedToBuilding(building, selectAll)
239:       this.syncSelectionViews()
240:     },
241:     onListSelectionChange(selection) {
242:       if (this.isSyncingSelection) return
243:       const selectedIds = new Set(selection.map((item) => item.houseId))
244:       this.buildingTableData.forEach((floor) => {
245:         floor.unitHouses?.forEach((unit) => {
246:           unit.tlpHouses?.forEach((house) => {
247:             house.checked = selectedIds.has(house.houseId) ? '1' : '0'
248:           })
249:         })
250:       })
251:       const selectedId = this.$refs.dialog?.treeSelection?.[this.buildingCheckCache.treeKey]
252:       this.notifyBuildingSelectChange(selectedId ? [selectedId] : null)
253:     },
254:     onBuildingTableCellClick() {
255:       const selectedId = this.$refs.dialog?.treeSelection?.[this.buildingCheckCache.treeKey]
256:       this.notifyBuildingSelectChange(selectedId ? [selectedId] : null)
257:     },
258:     collectSelectedHousesFromTree() {
259:       const selectionData = []
260:       this.forEachHouseInTreeData((house) => {
261:         if (house.exist == 1) return
262:         if (this.isHouseChecked(house)) {
263:           selectionData.push(house)
264:         }
265:       })
266:       return selectionData
267:     }
268:   }
269: }

