103:       const { dialog, treeKey } = this.getDialogTreeMeta()
104:       const selectedKey = dialog?.treeSelection?.[treeKey]
105:       if (selectedKey != null && selectedKey === building?.[treeKey]) {
106:         this.setFloorsChecked(this.buildingTableData, checked)
107:       }
108:     },
109:     initAllHousesInTree() {
110:       this.forEachHouseInTreeData((house) => {
111:         this.initHouseChecked(house)
112:       })
113:     },
114:     computeBuildingState(building) {
115:       let hasHouse = false
116:       let allSelected = true
117:       let anySelected = false
118: 
119:       this.forEachHouseInBuildingSource(building, (house) => {
120:         hasHouse = true
121:         if (this.isHouseChecked(house)) {
122:           anySelected = true
123:         } else {
124:           allSelected = false
125:         }
126:       })
127: 
128:       if (!hasHouse) {
129:         this.forEachHouseInBuilding(building, (house) => {
130:           hasHouse = true
131:           if (this.isHouseChecked(house)) {
132:             anySelected = true
133:           } else {
134:             allSelected = false
135:           }
136:         })
137:       }
138: 
139:       return {
140:         hasHouse,
141:         allSelected: hasHouse && allSelected,
142:         anySelected,
143:         indeterminate: anySelected && !(hasHouse && allSelected)
144:       }
145:     },
146:     rebuildGlobalCheckState(byId, treeData, treeKey) {
147:       let allSelected = true
148:       let anySelected = false
149: 
150:       treeData.forEach((building) => {
151:         const state = byId[building[treeKey]] || {
152:           hasHouse: false,
153:           allSelected: false,
154:           anySelected: false,
155:           indeterminate: false
156:         }
157:         if (!state.hasHouse) {
158:           allSelected = false
159:           return
160:         }
161:         if (state.allSelected) {
162:           anySelected = true
163:         } else {
164:           allSelected = false
