// 汇总所有楼幢（含已点选/未点选）的房屋为扁平列表，用于「列表视图」多幢房屋统一核对
flattenAllBuildingsHouses() {
  // 依赖 buildingSelectRevision，确保楼幢树加载/勾选变化后列表视图能响应式刷新
  void this.buildingSelectRevision
  const list = []
  this.forEachHouseInTreeData((house, { floor, unit }) => {
    list.push({
      ...house,
      floorName: floor.floorName,
      unitName: unit.unitName || unit.unitId
    })
  })
  return list
},

